/** Notificações do topo: tudo tirado dos dados (pagamentos para aprovar, extrato sem categoria, fechamento, riscos do fluxo). */
function avisosTopo() {
  const l = [], pend = db.pags.filter((p) => p.st === 'pendente' && doEmp(p)), semCat = db.extrato.filter((e) => !N.categoria(db, e) && !e.pag && !e.rec && !e.mov).length, et = db.fech.filter((f) => !f.ok).length;
  const atr = (db.recs || []).filter((r) => doEmp(r) && N.situacaoRec(r).st === 'atrasado'); if (atr.length) l.push({ tipo: 'ru', t: `${atr.length} recebível(is) atrasado(s)`, s: RC(atr.reduce((a, r) => a + N.faltaTitulo(r), 0)), ir: 'receber' });
  N.tesouraria(db, db.emp).filter((t) => t.insuficiente).forEach((t) => l.push({ tipo: 'ru', t: `Saldo de ${empNome(t.emp)} não cobre 7 dias`, s: `disponível ${RC(t.total)}, a pagar ${RC(t.pagar)}`, ir: 'tesouraria' }));
  if (pend.length) l.push({ tipo: 'at', t: `${pend.length} pagamento(s) para aprovar`, s: RC(pend.reduce((a, p) => a + p.c, 0)), ir: 'aprovar' });
  const al = calcFluxo().alertas.filter((x) => x.tipo === 'erro'); if (al.length) l.push({ tipo: 'ru', t: 'Saldo negativo no fluxo', s: `a partir da semana ${al[0].semana + 1}`, ir: 'caixa' });
  if (semCat) l.push({ tipo: 'at', t: `${semCat} linha(s) do extrato sem categoria`, s: 'crie uma regra na Conciliação', ir: 'conciliar' });
  if (et && !travado()) l.push({ tipo: '', t: `${et} etapa(s) do fechamento`, s: N.nomeComp(COMP), ir: 'fechar' });
  return l;
}
